begin;
set local search_path=public,extensions;
set local timezone='America/Sao_Paulo';
select extensions.no_plan();
insert into public.barbershops(id,name,slug,segment) values('da900000-0000-4000-8000-000000000001','Usage Fixture','usage-fixture','Confeitaria');
insert into public.saas_clients(id,name,segment,contact_name,owner_email,origin,plan,monthly_fee,status,barbershop_id)
values('da700000-0000-4000-8000-000000000001','Usage Fixture','Confeitaria','Fixture','usage@example.invalid','Teste','Catálogo Completo',29.90,'Ativo','da900000-0000-4000-8000-000000000001');
insert into public.billing_customers(saas_client_id,billing_email) values('da700000-0000-4000-8000-000000000001','usage@example.invalid');
insert into public.platform_subscriptions(billing_customer_id,product_id,plan_id,status,billing_cycle,base_amount,current_period_start,current_period_end)
select bc.id,p.product_id,p.id,'active','monthly',29.90,now(),now()+interval '30 days' from public.billing_customers bc,public.saas_plans p where bc.saas_client_id='da700000-0000-4000-8000-000000000001' and p.code='catalogo-completo';
insert into auth.users(id,instance_id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
 ('da800000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','usage-admin@example.invalid','{}','{}',now(),now()),
 ('da800000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','usage-owner@example.invalid','{}','{}',now(),now());
insert into public.profiles(id,barbershop_id,full_name,role,active) values ('da800000-0000-4000-8000-000000000001','da900000-0000-4000-8000-000000000001','Usage Admin','admin',true),('da800000-0000-4000-8000-000000000002','da900000-0000-4000-8000-000000000001','Usage Owner','owner',true);
insert into public.platform_admins(user_id) values('da800000-0000-4000-8000-000000000001');
create function pg_temp.usage_event(kind text,page_code text default 'home',person text default '1',action text default '',amount integer default 0) returns jsonb
language sql as $$ select jsonb_build_object('id',gen_random_uuid(),'visitor_id','da100000-0000-4000-8000-'||lpad(person,12,'0'),'session_id','da200000-0000-4000-8000-'||lpad(person,12,'0'),'visit_id','da300000-0000-4000-8000-'||lpad(person,12,'0'),'occurred_at',floor(extract(epoch from clock_timestamp())*1000000)::bigint,'event',kind,'page',page_code,'target',action,'value',amount,'source','instagram','device','mobile') $$;
create function pg_temp.usage_report(scope text default 'all') returns jsonb language sql as $$ select public.platform_usage_report((now() at time zone 'America/Sao_Paulo')::date,(now() at time zone 'America/Sao_Paulo')::date,scope) $$;
create temporary table usage_fixture(payload jsonb);
insert into usage_fixture select jsonb_build_array(pg_temp.usage_event('page_view'),pg_temp.usage_event('click','home','1','hero_signup'),pg_temp.usage_event('scroll','home','1','',75),pg_temp.usage_event('engagement','home','1','',30),pg_temp.usage_event('page_view','signup'),pg_temp.usage_event('signup_started','signup'),pg_temp.usage_event('signup_submitted','signup'),pg_temp.usage_event('signup_completed','signup'));
grant select on usage_fixture to anon,authenticated;
set local role anon;
select extensions.throws_ok($$select * from private.platform_usage_events$$,'42501',null,'visitors cannot read event rows');
select extensions.throws_ok($$select public.platform_usage_report(current_date,current_date,'all')$$,'42501',null,'visitors cannot read reports');
select extensions.is(public.public_record_platform_usage((select payload from usage_fixture))->>'accepted','8','bounded anonymous batch accepted');
select extensions.is(public.public_record_platform_usage((select payload from usage_fixture))->>'accepted','0','retry is idempotent');
select extensions.throws_ok($$select public.public_record_platform_usage('[]')$$,'22023',null,'empty batch rejected');
select extensions.throws_ok($$select public.public_record_platform_usage('{}')$$,'22023',null,'object batch rejected');
select extensions.throws_ok($$select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('page_view')||'{"email":"secret@example.invalid"}'::jsonb))$$,'22023',null,'extra personal data fields rejected');
select extensions.throws_ok($$select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('page_view')||'{"page":"/pedido/?token=secret"}'::jsonb))$$,'22023',null,'raw paths and query tokens rejected');
select extensions.throws_ok($$select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('click')||'{"target":"Senha digitada"}'::jsonb))$$,'22023',null,'free-form DOM text rejected');
select extensions.throws_ok($$select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('page_view')||'{"source":"email@example.invalid"}'::jsonb))$$,'22023',null,'free-form attribution rejected');
select extensions.throws_ok($$select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('scroll','home','1','',100)))$$,'22023',null,'unsupported scroll values rejected');
select extensions.throws_ok($$select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('engagement')||'{"value":1.5}'::jsonb))$$,'22023',null,'fractional values rejected');
select extensions.throws_ok($$select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('page_view')||'{"visitor_id":"invalid"}'::jsonb))$$,'22023',null,'invalid identifier rejected');
select extensions.throws_ok($$select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('page_view'),pg_temp.usage_event('page_view','home','2')))$$,'22023',null,'mixed sessions rejected');
select extensions.throws_ok($$select public.public_record_platform_usage((select jsonb_agg(pg_temp.usage_event('page_view')) from generate_series(1,21)))$$,'22023',null,'oversized batch rejected');
select extensions.throws_ok($$select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('page_view')||'{"created_at":"2000-01-01"}'::jsonb))$$,'22023',null,'client cannot override server timestamp fields');
select extensions.throws_ok($$select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('page_view')||'{"occurred_at":946684800000000}'::jsonb))$$,'22023',null,'old client event clock rejected');
select extensions.throws_ok($$select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('page_view')||'{"occurred_at":4102444800000000}'::jsonb))$$,'22023',null,'future client event clock rejected');
select extensions.throws_ok($$select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('page_view')||'{"page":null}'::jsonb))$$,'22023',null,'null fields rejected');
select extensions.throws_ok($$select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('page_view','home','2')||'{"session_id":"da200000-0000-4000-8000-000000000001"}'::jsonb))$$,'22023',null,'one visitor cannot reuse another visitor session');
select set_config('request.headers','{"origin":"https://evil.example"}',true);
select extensions.throws_ok($$select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('page_view')))$$,'42501',null,'foreign website origin rejected');
select set_config('request.headers','{"origin":"https://ogritech.com.br","cf-connecting-ip":"192.0.2.55"}',true);
select extensions.is(public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('page_view','storefront','2')))->>'accepted','1','own website origin accepted');
reset role;
select extensions.is((select count(*) from private.platform_usage_events),9::bigint,'invalid batches did not add partial events');
select extensions.ok((select bool_and(length(subject_hash)=64 and subject_hash !~ '192\\.0') from private.platform_usage_rate_buckets),'rate buckets store a secret-derived code, not raw address');
select extensions.ok(not exists(select 1 from information_schema.columns where table_schema='private' and table_name='platform_usage_events' and column_name in ('email','phone','user_id','url','ip','headers','text')),'event schema has no identity or raw-content columns');
update private.platform_usage_rate_buckets set event_count=1200;
set local role anon;
select extensions.is(public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('click','storefront','2','photo')))->>'limited','true','minute abuse limit stops new writes');
reset role;
select extensions.is((select count(*) from private.platform_usage_events),9::bigint,'limited request never stores events');
select set_config('request.headers','{}',true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"da800000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select extensions.throws_ok($$select pg_temp.usage_report()$$,'42501',null,'establishment owner cannot inspect global traffic');
select extensions.throws_ok($$select * from private.platform_usage_sessions$$,'42501',null,'authenticated clients cannot read sessions directly');
select set_config('request.jwt.claims','{"sub":"da800000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.is(pg_temp.usage_report()->'summary'->>'visitors','2','admin receives distinct browser estimates');
select extensions.is(pg_temp.usage_report()->'summary'->>'sessions','2','session count deduplicated');
select extensions.is(pg_temp.usage_report()->'summary'->>'page_views','3','page views counted independently of clicks');
select extensions.is(pg_temp.usage_report('site')->'summary'->>'visitors','1','site filter excludes public storefront visitors');
select extensions.is(pg_temp.usage_report('storefront')->'summary'->>'visitors','1','storefront filter is independent');
select extensions.is(pg_temp.usage_report()->'signup_funnel'->3->>'count','1','ordered signup funnel counts completed flow');
select extensions.is(pg_temp.usage_report()->'paths'->0->>'previous','home','journey starts with previous page view');
select extensions.is(pg_temp.usage_report()->'paths'->0->>'page','signup','journey destination uses fixed page label');
select extensions.is(pg_temp.usage_report()->'sources'->0->>'source','instagram','attribution source preserved');
select extensions.is(pg_temp.usage_report()->'daily'->0->>'page_views','3','local daily totals agree');
select extensions.ok(pg_temp.usage_report()::text !~ 'da100000|da200000|da300000|192.0.2.55','report never exposes session, visitor or rate identifiers');
select extensions.throws_ok($$select public.platform_usage_report(current_date,current_date-1,'all')$$,'22023',null,'reversed range rejected');
select extensions.throws_ok($$select public.platform_usage_report(current_date-100,current_date,'all')$$,'22023',null,'unbounded date range rejected');
select extensions.throws_ok($$select public.platform_usage_report(current_date,current_date+1,'all')$$,'22023',null,'future period rejected');
select extensions.throws_ok($$select public.platform_usage_report(current_date,current_date,'unknown')$$,'22023',null,'unknown surface rejected');
reset role;
-- A completed event before submission must never count as a conversion.
insert into private.platform_usage_sessions(id,visitor_id,source,device) values('da200000-0000-4000-8000-000000000003','da100000-0000-4000-8000-000000000003','direct','desktop');
insert into private.platform_usage_events(id,session_id,visitor_id,visit_id,event,page,target,value,created_at)
select gen_random_uuid(),'da200000-0000-4000-8000-000000000003','da100000-0000-4000-8000-000000000003','da300000-0000-4000-8000-000000000003',kind,'signup','',0,((now() at time zone 'America/Sao_Paulo')::date::timestamp at time zone 'America/Sao_Paulo')+make_interval(secs=>pos)
from (values('page_view',1),('signup_completed',2),('signup_started',3),('signup_submitted',4)) v(kind,pos);
set local role authenticated;
select extensions.is(pg_temp.usage_report()->'signup_funnel'->0->>'count','2','incomplete visitor enters funnel denominator');
select extensions.is(pg_temp.usage_report()->'signup_funnel'->3->>'count','1','out-of-order completion is excluded');
select extensions.is(pg_temp.usage_report('app')->'summary'->>'page_views','0','empty surface is reported as empty, not fabricated traffic');
select extensions.is(jsonb_array_length(public.platform_usage_report(current_date-6,current_date,'all')->'daily'),7,'empty dates remain visible in the chart');
select extensions.ok(not has_function_privilege('authenticated','private.prune_platform_usage()','execute'),'retention cannot be invoked by users');
reset role;
create temporary table usage_clock as select floor(extract(epoch from clock_timestamp()-interval '10 seconds')*1000000)::bigint base;
grant select on usage_clock to anon;
set local role anon;
select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('signup_completed','signup','5')||jsonb_build_object('occurred_at',(select base+3000000 from usage_clock))));
select public.public_record_platform_usage(jsonb_build_array(pg_temp.usage_event('page_view','signup','5')||jsonb_build_object('occurred_at',(select base from usage_clock)),pg_temp.usage_event('signup_started','signup','5')||jsonb_build_object('occurred_at',(select base+1000000 from usage_clock)),pg_temp.usage_event('signup_submitted','signup','5')||jsonb_build_object('occurred_at',(select base+2000000 from usage_clock))));
reset role;
set local role authenticated;
select extensions.is(public.platform_usage_report(current_date-1,current_date,'all')->'signup_funnel'->3->>'count','2','network arrival order does not change the real conversion sequence');
reset role;
select extensions.ok((select bool_and(created_at<=received_at+interval '5 minutes') from private.platform_usage_events),'reported occurrence times stay within the accepted clock window');
update public.profiles set active=false where id='da800000-0000-4000-8000-000000000001';
set local role authenticated;
select extensions.throws_ok($$select pg_temp.usage_report()$$,'42501',null,'inactive administrator rejected server-side');
reset role;
insert into private.platform_usage_sessions(id,visitor_id,source,device,started_at,last_seen_at) values('da200000-0000-4000-8000-000000000004','da100000-0000-4000-8000-000000000004','direct','mobile',now()-interval '91 days',now()-interval '91 days');
insert into private.platform_usage_events(id,session_id,visitor_id,visit_id,event,page,created_at,received_at) values(gen_random_uuid(),'da200000-0000-4000-8000-000000000004','da100000-0000-4000-8000-000000000004',gen_random_uuid(),'page_view','home',now()-interval '91 days',now()-interval '91 days');
insert into private.platform_usage_rate_buckets values('expired-test',now()-interval '3 days',1);
select private.prune_platform_usage();
select extensions.ok(not exists(select 1 from private.platform_usage_sessions where id='da200000-0000-4000-8000-000000000004'),'retention removes expired sessions');
select extensions.ok(not exists(select 1 from private.platform_usage_events where created_at<now()-interval '90 days'),'retention removes expired events');
select extensions.ok(not exists(select 1 from private.platform_usage_rate_buckets where subject_hash='expired-test'),'retention removes expired abuse signals');
select extensions.is((select count(*) from private.platform_usage_events where session_id='da200000-0000-4000-8000-000000000001'),8::bigint,'retention preserves recent events');
select * from extensions.finish();
rollback;
